// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Reentrance} from "../src/Reentrance.sol";

contract InvMutTest is Test {
    Reentrance c;
    function setUp() public { c = new Reentrance(); }
    function testRegression_property() public {
        address user = address(0x1234);
        vm.deal(user, 1 ether);
        vm.prank(user);
        c.addToBalance{value: 1 ether}();
        uint balanceBefore = address(user).balance;
        vm.prank(user);
        bool ok;
        try c.withdrawBalance() {
            ok = true;
        } catch {
            ok = false;
        }
        assertTrue(ok);
        uint balanceAfter = address(user).balance;
        assertEq(balanceAfter, balanceBefore + 1 ether);
    }
}
